"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["55535"],{56894(e){e.exports=JSON.parse('{"id":"V4-112","slug":"order-book","term":"Order Book","also_known_as":[],"difficulty":"Intermediate","definition":"An order book is an electronic list of all outstanding buy and sell orders for a security, organised by price, showing how many shares or units buyers want to buy and sellers want to sell at each price level.","explanation":["Exchanges and trading platforms use order books to match buyers and sellers. Buy orders, called bids, are listed from the highest price downwards. Sell orders, called offers or asks, are listed from the lowest price upwards.","The highest bid and lowest ask form the best prices, and the gap between them is the bid-ask spread. When a buy order matches a sell order at the same price, a trade happens.","For example, an order book might show buyers wanting 2,000 shares at 49.98 and 5,000 at 49.97, and sellers offering 1,500 shares at 50.00 and 4,000 at 50.01. A market order to buy 1,500 shares would be filled at 50.00.","The order book shows market depth and liquidity. A deep order book, with large orders near the current price, means large trades can be made without moving the price much. Traders watch order books to gauge supply and demand, although some large orders are hidden or split into smaller pieces."],"note":"","total":1725,"prev":{"slug":"option-premium","term":"Option Premium"},"next":{"slug":"ordinary-annuity","term":"Ordinary Annuity"}}')}}]);